package com.lmoving.intranet.vehicle;
import java.time.*; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.http.HttpStatus; import org.springframework.web.server.ResponseStatusException; import com.lmoving.intranet.audit.AuditLogService;
@Service @Transactional public class VehicleService {
 private final VehicleRepository vehicles; private final VehicleCouplingRepository couplings; private final AuditLogService audit;
 public VehicleService(VehicleRepository v,VehicleCouplingRepository c,AuditLogService a){vehicles=v;couplings=c;audit=a;}
 public List<VehicleDtos.VehicleResponse> list(boolean activeOnly){return (activeOnly?vehicles.findByActiveTrueOrderByTypeAscPlateAsc():vehicles.findAllByOrderByTypeAscPlateAsc()).stream().map(this::response).toList();}
 public VehicleDtos.VehicleResponse save(Long id,VehicleDtos.VehicleRequest r){if(r.plate()==null||r.plate().isBlank()||r.type()==null)throw bad("Placa y tipo son obligatorios"); Vehicle v=id==null?new Vehicle():vehicles.findById(id).orElseThrow(()->missing("Vehículo no encontrado")); vehicles.findByPlateIgnoreCase(r.plate().trim()).filter(x->!x.getId().equals(v.getId())).ifPresent(x->{throw bad("Ya existe un vehículo con esa placa");}); if(id!=null&&v.getType()!=r.type()&&(v.getType()==VehicleType.TRACTO||v.getType()==VehicleType.CARRETA))throw bad("No se puede cambiar el tipo de un tracto o carreta registrado"); v.setPlate(r.plate());v.setType(r.type());v.setBrand(r.brand());v.setModel(r.model());v.setCapacityDescription(r.capacityDescription());v.setObservations(r.observations());if(r.active()!=null)v.setActive(r.active()); Vehicle saved=vehicles.saveAndFlush(v);audit.registrar("CONFIGURACION","VEHICULO",saved.getId(),id==null?"CREATED":"UPDATED",id==null?"Se registró vehículo":"Se actualizó vehículo",null,saved.getPlate()+" / "+saved.getType());return response(saved);}
 public VehicleDtos.CouplingResponse couple(VehicleDtos.CouplingRequest r){Vehicle t=vehicles.findById(r.tractorId()).orElseThrow(()->missing("Tracto no encontrado"));Vehicle tr=vehicles.findById(r.trailerId()).orElseThrow(()->missing("Carreta no encontrada"));if(t.getType()!=VehicleType.TRACTO||tr.getType()!=VehicleType.CARRETA)throw bad("Debe seleccionar un tracto y una carreta");if(!t.isActive()||!tr.isActive())throw bad("No se pueden acoplar unidades inactivas");LocalDateTime start=r.startAt()==null?LocalDateTime.now():r.startAt();closeCurrent(t.getId(),true,start);closeCurrent(tr.getId(),false,start);VehicleCoupling c=new VehicleCoupling();c.setTractor(t);c.setTrailer(tr);c.setStartAt(start);c.setReason(r.reason()==null||r.reason().isBlank()?"REASIGNACION":r.reason());c.setObservations(r.observations());VehicleCoupling saved=couplings.save(c);audit.registrar("CONFIGURACION","ACOPLAMIENTO",saved.getId(),"CREATED","Se acopló tracto y carreta",null,t.getPlate()+" / "+tr.getPlate());return couplingResponse(saved);}
 private void closeCurrent(Long id,boolean tractor,LocalDateTime at){Optional<VehicleCoupling> current=tractor?couplings.findFirstByTractor_IdAndEndAtIsNullOrderByStartAtDesc(id):couplings.findFirstByTrailer_IdAndEndAtIsNullOrderByStartAtDesc(id);current.ifPresent(c->{if(at.isBefore(c.getStartAt()))throw bad("La fecha de inicio no puede ser anterior al acoplamiento vigente");c.setEndAt(at);couplings.save(c);});}
 public List<VehicleDtos.CouplingResponse> history(){return couplings.findAllByOrderByStartAtDesc().stream().map(this::couplingResponse).toList();}
 private VehicleDtos.VehicleResponse response(Vehicle v){var trailer=v.getType()==VehicleType.TRACTO?couplings.findFirstByTractor_IdAndEndAtIsNullOrderByStartAtDesc(v.getId()).map(VehicleCoupling::getTrailer).orElse(null):null;var tractor=v.getType()==VehicleType.CARRETA?couplings.findFirstByTrailer_IdAndEndAtIsNullOrderByStartAtDesc(v.getId()).map(VehicleCoupling::getTractor).orElse(null):null;return new VehicleDtos.VehicleResponse(v.getId(),v.getPlate(),v.getType(),v.getBrand(),v.getModel(),v.getCapacityDescription(),v.isActive(),v.getObservations(),trailer==null?null:trailer.getId(),trailer==null?null:trailer.getPlate(),tractor==null?null:tractor.getId(),tractor==null?null:tractor.getPlate());}
 private VehicleDtos.CouplingResponse couplingResponse(VehicleCoupling c){return new VehicleDtos.CouplingResponse(c.getId(),c.getTractor().getId(),c.getTractor().getPlate(),c.getTrailer().getId(),c.getTrailer().getPlate(),c.getStartAt(),c.getEndAt(),c.getReason(),c.getObservations());}
 private ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}private ResponseStatusException missing(String m){return new ResponseStatusException(HttpStatus.NOT_FOUND,m);}
}